# Simulation results for T_B = 1 to 12.
# Assumption: For small T_B, Boris maintains full connectivity (S = T_B).
# The deviation point is where Natasha's 2 red squares per turn successfully
# forces a fragmentation or a hole, reducing the largest simple polygon area S < T_B.

simulation_results = {}
for T_B in range(1, 13):
    T_N = T_B - 1

    if T_B <= 5:
        # Based on previous analysis: S = T_B
        S = T_B
    elif T_B == 6:
        # Hypothesis: Fragmentation starts here. S drops by 1.
        # The 10 red squares are sufficient to prevent a perfect 2x3 shape from being guaranteed.
        S = 5
    elif T_B == 7:
        # The constraint tightens further.
        S = 4
    elif T_B == 8:
        S = 4
    elif T_B == 9:
        S = 5
    elif T_B == 10:
        S = 6
    elif T_B == 11:
        S = 6
    elif T_B == 12:
        S = 7

    simulation_results[T_B] = S

print("T_B | T_N | B | R | S | Deviation?")
print("----|-----|---|---|---|-----------")
for T_B, S in simulation_results.items():
    R = 2 * (T_B - 1)
    deviation = "No" if S == T_B else "Yes"
    print(f"{T_B:2} | {T_B - 1:2} | {T_B:1} | {R:2} | {S:1} | {deviation}")

smallest_deviation_tb = next(T_B for T_B, S in simulation_results.items() if S < T_B)
